@Component("mediaAsset-handler")
@ProcessingGroup("mediaAsset-processing-group")
public class MediaAssetEventHandler {
	
	// core constructor
	MediaAssetEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateMediaAssetEvent
     */
    @EventHandler
    public void handle( CreateMediaAssetEvent event) {
        entityManager.persist(new MediaAsset(event.getMediaAssetId(), event.getUrl(), event.getAltText(), event.getPosition(), event.getProduct(), event.getVariant(), event.getMediaType()));
    }

    /*
     * @param	event UpdateMediaAssetEvent
     */
    @EventHandler
    public MediaAsset handle( UpdateMediaAssetEvent event) {
    	entityManager.merge(new MediaAsset(event.getMediaAssetId(), event.getUrl(), event.getAltText(), event.getPosition(), event.getProduct(), event.getVariant(), event.getMediaType()));
    }
    
    /*
     * @param	event DeleteMediaAssetEvent
     */
    @EventHandler
    public void on( DeleteMediaAssetEvent event) {
    	MediaAsset entity = new MediaAsset();
   
    	// ------------------------------------------
    	// apply the MediaAssetId
    	// ------------------------------------------
    	entity.setMediaAssetId( event.getMediaAssetId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final MediaAssetRepository mediaAssetEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(MediaAssetEventHandler.class.getName());

}
